import React, { useRef } from 'react';
import { iconDependencies } from './neon-icon';
import { avatarDependencies } from './neon-avatar';
import { tagDependencies } from './neon-tag';
import { listItemPopperDependencies } from './neon-item-picker';
import { buildPropsMap, createComponentDependency, useImperativeProps, useListeners, toAttribute, withNeonWebComponent } from './utils/react-utils';
import { iconStackDependencies } from './neon-icon-stack';
import { tooltipDependencies } from './neon-tooltip';
import { illustrationSimpleDependencies } from './neon-illustration-simple';
// import {gradeBlockDependencies} from './neon-grade-block';
const clickableItemSelector = '[data-slot="list-item-actions"] button, [data-slot="list-item-actions"] a, [data-slot="list-item-actions"] input[type="checkbox"], [data-slot="list-item-actions"] input[type="radio"], [data-slot="list-item-actions"] label';
export const listItemDependencies = [
    createComponentDependency('list-item'),
    ...iconDependencies,
    ...avatarDependencies,
    ...listItemPopperDependencies,
    ...tagDependencies,
    ...iconStackDependencies,
    ...tooltipDependencies,
    ...illustrationSimpleDependencies
    // ...gradeBlockDependencies,
];
function ListItem(props) {
    const elementRef = useRef();
    // * * * Set Props * * *
    useImperativeProps(elementRef, {
        value: props.value
    });
    // * * * Set Listeners * * *
    useListeners(elementRef, {
        click: (e) => {
            if (props.onClick != null) {
                if ((!e.target.matches(clickableItemSelector) && e.target.closest(clickableItemSelector) == null) || props.letAllClicksThrough) {
                    props.onClick(e);
                }
            }
        },
        valueChange: (event) => {
            if (props.valueChange != null) {
                props.valueChange(event.target.value, event);
            }
        }
    });
    // * * * Set Attributes * * *
    return React.createElement('neon-2_20_1-list-item', buildPropsMap(props, {
        ref: elementRef,
        disabled: toAttribute(props.disabled),
        'data-control-type': props.dataControlType,
        'data-border-type': props.dataBorderType,
        'data-is-nested': toAttribute(props.dataIsNested),
        'data-is-selected': toAttribute(props.dataIsSelected),
        'data-aria-label': props.dataAriaLabel,
        'data-text': props.dataText,
        'data-text-size': props.dataTextSize,
        'data-text-weight': props.dataTextWeight,
        'data-subtext': props.dataSubtext,
        'data-text-right': props.dataTextRight,
        'data-body': props.dataBody,
        'data-highlight-text': props.dataHighlightText,
        'data-illustration-simple': props.dataIllustrationSimple,
        'data-illustration-simple-size': props.dataIllustrationSimpleSize,
        'data-icon': props.dataIcon,
        'data-icon-color': props.dataIconColor,
        'data-icon-color-weight': props.dataIconColorWeight,
        'data-icon-right': props.dataIconRight,
        'data-icon-right-color': props.dataIconRightColor,
        'data-icon-right-color-weight': props.dataIconRightColorWeight,
        'data-icon-stack-icon': props.dataIconStackIcon,
        'data-icon-stack-color': props.dataIconStackColor,
        'data-icon-stack-shape': props.dataIconStackShape,
        'data-icon-stack-size': props.dataIconStackSize,
        'data-icon-stack-type': props.dataIconStackType,
        'data-icon-stack-position': props.dataIconStackPosition,
        'data-image-src': props.dataImageSrc,
        'data-show-avatar': toAttribute(props.dataShowAvatar),
        'data-avatar-size': props.dataAvatarSize,
        'data-avatar-first-name': props.dataAvatarFirstName,
        'data-avatar-last-name': props.dataAvatarLastName,
        'data-avatar-profile-picture-src': props.dataAvatarProfilePictureSrc,
        'data-avatar-background-option': props.dataAvatarBackgroundOption,
        'data-url': props.dataUrl,
        'data-open-in-new-tab': toAttribute(props.dataOpenInNewTab),
        'data-tag-text': props.dataTagText,
        'data-tag-subtext': props.dataTagSubtext,
        'data-tag-position': props.dataTagPosition,
        'data-tag-type': props.dataTagType,
        'data-children-icon': props.dataChildrenIcon,
        'data-checkbox-position': props.dataCheckboxPosition,
        'data-menu-popper-placement': props.dataMenuPopperPlacement,
        'data-tooltip-placement': props.dataTooltipPlacement || props.dataPopperPlacement,
        'data-tooltip-text': props.dataTooltipText,
        'data-menu-size': props.dataMenuSize,
        'data-constrain-width': props.dataConstrainWidth,
        name: props.name
        // 'data-show-select-all': props.dataShowSelectAll
        // 'data-gradeblock-color': props.dataGradeblockColor,
        // 'data-gradeblock-number': props.dataGradeBlockNumber,
        // 'data-grade': props.dataGrade,
        // 'data-gradeblock-position': props.dataGradeBlockPosition,
    }), props.children);
}
export const NeonListItem = withNeonWebComponent('neon-2_20_1-list-item', ListItem, listItemDependencies);
